for r in rows:
    matching=logs.get(r['id']+'_PDF',logs.get(r['id']))
    if matching:
        r['hasil_akses_langsung']=matching['status']
        r['berkas_lokal']=matching.get('berkas','')
        r['sha256']=matching.get('sha256','')
        r['error_akses']=matching.get('error','')
    else:r.update(hasil_akses_langsung='Lihat status verifikasi',berkas_lokal='',sha256='',error_akses='')
    if r['id']=='BPS_IPTK_2026':r['berkas_lokal']='data/raw/BPS_IPTK_Feb2026.pdf'
    if r['id']=='SAK2025_NON_DISEMINASI':r['berkas_lokal']='data/raw/SAK2025_NON_DISEMINASI.pdf'
    if r['id']=='SAK2025_DOCUMENTATION':r['berkas_lokal']='data/raw/SAK2025_KUESIONER.pdf; data/raw/SAK2025_DOCUMENTATION.zip'
    if r['id']=='KARIRHUB2025':r['hasil_akses_langsung']='HTTP 200 tetapi hanya shell aplikasi; data XLSX belum diperoleh'
    if r['id']=='PAUD_REFERENSI':r['hasil_akses_langsung']='Laman tersedia; dataset daftar satuan nasional belum diekspor'
    if r['id']=='SDI_GEOMETRI':
        r['hasil_akses_langsung']='Laman dan ZIP berhasil; geometri Polyline diperiksa, ditolak sebagai polygon'
        r['berkas_lokal']='data/raw/SDI_GEOMETRI.html; data/raw/KEMENDAGRI_WFS_ZIP.zip; data/processed/audit_geometri_sdi.json'
fields=list(rows[0])
with (ROOT/'katalog_sumber.csv').open('w',encoding='utf-8-sig',newline='') as f:
    w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
(ROOT/'katalog_sumber.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8')
aspects=['Partisipasi dan dinamika kerja','Keinginan bekerja','Ekonomi','Status perkawinan','Umur','Pendidikan','Pengasuhan','Akses digital','Transportasi','Akses pekerjaan','Struktur ekonomi','Riwayat berhenti kerja','Kesehatan dan disabilitas','Norma sosial','Kualitas pekerjaan','Geometri dan kode wilayah','Mutu data']
parts=['# Katalog sumber menurut aspek','Tanggal akses: 24 Oktober 2026. Satu sumber dapat muncul di beberapa aspek; pengulangan bukan penelitian independen. Status akses mikrodata dipisahkan dari dokumentasi yang terbuka.','Keterangan: PDF kamus/kuesioner adalah dokumentasi, bukan data individu penuh. Halaman HTTP 200 belum membuktikan tabel dapat diekspor.']
for a in aspects:
    parts.append('\n## '+a)
    for r in rows:
        if a not in r['aspek'].split(';'):continue
        parts.append(f"\n### {r['id']} — {r['judul']}\n\n- Sumber: [{r['produsen']}]({r['url']}).\n- Periode dan cakupan: {r['periode']}; {r['level_tersedia']}.\n- Dicari: {r['indikator_diusulkan']}.\n- Peran: {r['peran_urgensi']}.\n- Batas: {r['batas']}.\n- Verifikasi: {r['status_verifikasi']}; {r['hasil_akses_langsung']}.\n- Berkas lokal: {r['berkas_lokal'] or 'Belum ada berkas numerik lokal untuk sumber ini.'}")
(ROOT/'02_katalog_sumber_per_aspek.md').write_text('\n'.join(parts)+'\n',encoding='utf-8')
manifest=[]
for p in (ROOT/'data/raw').glob('*'):
    if p.is_file():manifest.append({'berkas':str(p.relative_to(ROOT)).replace('\\','/'),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
with (ROOT/'data/manifest_unduhan.csv').open('w',encoding='utf-8-sig',newline='') as f:
    w=csv.DictWriter(f,fieldnames=['berkas','bytes','sha256']);w.writeheader();w.writerows(manifest)
print(json.dumps({'sources':len(rows),'aspects':len(aspects),'files_raw':len(manifest)},indent=2))
